const $=id=>document.getElementById(id);
const labels={awaiting_funding:['Awaiting funding','Seller must wait for independently confirmed escrow funding.'],funded:['Funded · ready to ship','The seller can now add tracked, signature-required shipping.'],shipped:['In transit','A plain delivery scan or unsigned delivery is insufficient.'],inspection:['Buyer inspection','Signed delivery is reported. Buyer release or dispute review is still required.'],disputed:['Dispute open · release paused','The resolver reviews evidence and proposes an explained outcome.'],released:['Seller payout released','Simulated result: seller receives 0.98 XBT; marketplace receives 0.02 XBT; unused reserve returns to the buyer.'],refunded:['Buyer refunded','Simulated full refund: marketplace success fee waived. Actual network cost remains.'],split:['Split settlement','A reviewed split was simulated.']};
async function run(action){$('error').textContent='';try{const r=await fetch(action?'/action':'/state',{method:action?'POST':'GET',headers:action?{'Content-Type':'application/json'}:{},body:action?JSON.stringify({action}):undefined});const s=await r.json();if(!r.ok)throw Error(s.error);render(s);}catch(e){$('error').textContent=e.message;}}
function render(s){$('state').textContent=labels[s.state][0];$('explanation').textContent=labels[s.state][1];$('descriptor').textContent=s.contract.descriptor;$('approvals').replaceChildren(...s.approvals.map(a=>{const p=document.createElement('span');p.className='approval';p.textContent=a+' approved';return p;}));const buttons=[];if(s.state==='awaiting_funding')buttons.push(['fund','Simulate confirmed funding']);if(s.state==='funded')buttons.push(['ship','Seller ships with signature']);if(s.state==='shipped')buttons.push(['deliver','Simulate signed delivery'],['unsigned','Try unsigned delivery']);if(s.state==='inspection'&&!s.proposal)buttons.push(['release','Buyer proposes release']);if(s.state==='disputed'&&!s.proposal)buttons.push(['refund','Resolver proposes full refund']);if(s.proposal&&!['released','refunded','split'].includes(s.state)){const participants=s.state==='disputed'?['buyer','resolver']:['buyer','seller'];for(const role of participants)if(!s.approvals.includes(role))buttons.push([role,role+' approves this outcome']);buttons.push(['settle','Try finalizing settlement']);}if(['funded','shipped','inspection'].includes(s.state))buttons.push(['issue','Buyer raises an issue']);$('actions').replaceChildren(...buttons.map(([action,label],i)=>{const b=document.createElement('button');b.textContent=label;if(!i)b.className='primary';b.addEventListener('click',()=>run(action));return b;}));$('history').replaceChildren(...s.events.map(e=>{const li=document.createElement('li');li.textContent=e.actor+' · '+e.action;return li;}));}
$('reset').addEventListener('click',()=>run('reset'));run();
